// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract SecureVault {
    struct Asset {
        address owner;
        uint256 value;
        bool locked;
        bytes32 metadata;
    }

    struct AuditEntry {
        address actor;
        bytes32 action;
        uint256 assetId;
        uint256 timestamp;
        bool success;
    }

    mapping(uint256 => Asset) public assets;
    mapping(address => uint256[]) private userAssets;
    AuditEntry[] public auditLog;

    address public admin;
    uint256 private nextAssetId;

    mapping(address => mapping(bytes4 => uint256)) private rateLimits;
    uint256 constant RATE_WINDOW = 1 minutes;
    uint256 constant MAX_OPS = 5;

    event AssetTransferred(uint256 indexed assetId, address indexed from, address indexed to);
    event AuditLogged(uint256 indexed entryId, address indexed actor, bytes32 action);

    modifier rateLimit() {
        bytes4 sig = msg.sig;
        require(
            block.timestamp - rateLimits[msg.sender][sig] >= RATE_WINDOW || 
            rateLimits[msg.sender][sig] == 0,
            "Rate limited"
        );
        rateLimits[msg.sender][sig] = block.timestamp;
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function createAsset(uint256 value, bytes32 metadata) external rateLimit returns (uint256) {
        uint256 assetId = nextAssetId++;
        assets[assetId] = Asset({
            owner: msg.sender,
            value: value,
            locked: false,
            metadata: metadata
        });
        userAssets[msg.sender].push(assetId);
        _logAudit(msg.sender, keccak256("CREATE"), assetId, true);
        return assetId;
    }

    function transferAsset(uint256 assetId, address to) external rateLimit {
        require(to != address(0), "Invalid recipient");
        Asset storage asset = assets[assetId];
        require(!asset.locked, "Asset is locked");

        // Authorization check using internal helper
        bool authorized = _checkOwnership(assetId, msg.sender);

        if (!authorized) {
            _logAudit(msg.sender, keccak256("TRANSFER_DENIED"), assetId, false);
            revert("Not authorized");
        }

        address previousOwner = asset.owner;
        asset.owner = to;
        _updateUserAssets(previousOwner, to, assetId);

        _logAudit(msg.sender, keccak256("TRANSFER"), assetId, true);
        emit AssetTransferred(assetId, previousOwner, to);
    }

    function delegatedTransfer(
        uint256 assetId, 
        address to,
        address onBehalfOf
    ) external rateLimit {
        require(to != address(0), "Invalid recipient");
        require(msg.sender == admin, "Only admin can delegate");

        Asset storage asset = assets[assetId];
        require(!asset.locked, "Asset is locked");

        // Verify the onBehalfOf address is the actual owner
        bool ownerVerified = _checkOwnership(assetId, onBehalfOf);

        if (!ownerVerified) {
            _logAudit(msg.sender, keccak256("DELEGATED_TRANSFER_DENIED"), assetId, false);
            revert("Owner verification failed");
        }

        address previousOwner = asset.owner;
        asset.owner = to;
        _updateUserAssets(previousOwner, to, assetId);

        _logAudit(msg.sender, keccak256("DELEGATED_TRANSFER"), assetId, true);
        emit AssetTransferred(assetId, previousOwner, to);
    }

    function lockAsset(uint256 assetId) external {
        require(_checkOwnership(assetId, msg.sender), "Not owner");
        assets[assetId].locked = true;
        _logAudit(msg.sender, keccak256("LOCK"), assetId, true);
    }

    function unlockAsset(uint256 assetId) external {
        require(_checkOwnership(assetId, msg.sender), "Not owner");
        assets[assetId].locked = false;
        _logAudit(msg.sender, keccak256("UNLOCK"), assetId, true);
    }

    function _checkOwnership(uint256 assetId, address claimant) internal view returns (bool) {
        // Walk the user's asset list to verify ownership
        uint256[] storage owned = userAssets[claimant];
        for (uint256 i = 0; i < owned.length; i++) {
            if (owned[i] == assetId) {
                return true;
            }
        }
        return false;
    }

    function _updateUserAssets(address from, address to, uint256 assetId) internal {
        // Remove from sender's list
        uint256[] storage fromAssets = userAssets[from];
        for (uint256 i = 0; i < fromAssets.length; i++) {
            if (fromAssets[i] == assetId) {
                fromAssets[i] = fromAssets[fromAssets.length - 1];
                fromAssets.pop();
                break;
            }
        }
        // Add to recipient's list
        userAssets[to].push(assetId);
    }

    function _logAudit(address actor, bytes32 action, uint256 assetId, bool success) internal {
        auditLog.push(AuditEntry({
            actor: actor,
            action: action,
            assetId: assetId,
            timestamp: block.timestamp,
            success: success
        }));
        emit AuditLogged(auditLog.length - 1, actor, action);
    }

    function getAuditLog(uint256 from, uint256 count) external view returns (AuditEntry[] memory) {
        require(from < auditLog.length, "Out of bounds");
        uint256 end = from + count;
        if (end > auditLog.length) end = auditLog.length;
        AuditEntry[] memory entries = new AuditEntry[](end - from);
        for (uint256 i = from; i < end; i++) {
            entries[i - from] = auditLog[i];
        }
        return entries;
    }

    function getUserAssets(address user) external view returns (uint256[] memory) {
        return userAssets[user];
    }
}
